@forelse($changes as $change)<article class="sandbox-review-change"><h3>{{ $change->reversed_at ? 'Reversed acceptance' : 'Accepted changes' }} · {{ $change->created_at->asDateTime() }}</h3>@foreach($change->changes as $entry)<p>{{ $entry['key'] ?? 'Event participation' }}@if(isset($entry['after'])) · {{ $entry['after']['name'] ?? $entry['after']['title'] ?? $entry['after']['label'] ?? '' }}@endif</p>@endforeach @if(!$change->reversed_at)<p class="sandbox-help">Undo is refused if a record has newer changes. Created records are archived.</p><flux:button size="sm" icon="arrow-uturn-left" wire:click="reverseCanon({{ $change->id }})">Undo acceptance</flux:button>@endif</article>@empty<p>No sandbox ideas have been made canon in this exercise.</p>@endforelse
